# ── Helpers ─────────────────────────────────────────────────────────────────

def s(x): return str(x).strip() if x else ""
def blank(x): return s(x) == ""

def num(x):
    try: return float(s(x).replace(",","."))
    except: return None

def is_num(x): return num(x) is not None

def mki(product, sheet, sap_struct, sap_field, field_label, value, severity, msg, fix, code=""):
    return dict(product=product or "?", sheet=sheet, sap_structure=sap_struct,
                field=sap_field, field_label=field_label, current_value=s(value),
                severity=severity, issue=msg, fix=fix, ltmc_error_code=code)

# ── XML/Excel Parser ─────────────────────────────────────────────────────────

def read_uploaded_template(uploaded_file):
    """Read uploaded file - supports .xlsx, .xls, .xml"""
    fname = uploaded_file.name.lower()
    
    if fname.endswith((".xlsx", ".xls")):
        try:
            xl = pd.ExcelFile(uploaded_file, engine="openpyxl")
            sheets = {}
            for name in xl.sheet_names:
                df = pd.read_excel(xl, sheet_name=name, header=None, dtype=str).fillna("")
                sheets[name] = df
            return sheets, None
        except Exception as e:
            return {}, str(e)
    
    elif fname.endswith(".xml"):
        try:
            content = uploaded_file.read().decode("utf-8", errors="replace")
            return parse_spreadsheetml(content), None
        except Exception as e:
            return {}, str(e)
    
    return {}, "Unsupported file format. Please upload .xlsx, .xls, or .xml"

def parse_spreadsheetml(content):
    """Parse Microsoft SpreadsheetML (Excel XML) format"""
    sheets = {}
    ws_matches = re.finditer(r'(?:ss:)?Name="([^"]*)"[^>]*>(.*?)</(?:ss:)?Worksheet>', content, re.DOTALL)
    
    for match in ws_matches:
        sheet_name = match.group(1)
        sheet_content = match.group(2)
        
        rows_raw = re.findall(r'<(?:ss:)?Row[^>]*>(.*?)</(?:ss:)?Row>', sheet_content, re.DOTALL)
        parsed_rows = []
        for row in rows_raw:
            cells = re.findall(r'<(?:ss:)?Cell[^>]*>(.*?)</(?:ss:)?Cell>', row, re.DOTALL)
            vals = []
            for cell in cells:
                dm = re.search(r'<(?:ss:)?Data[^>]*>(.*?)</(?:ss:)?Data>', cell, re.DOTALL)
                if dm:
                    v = re.sub(r'&#10;|&#13;', " ", dm.group(1))
                    v = re.sub(r'<[^>]+>', "", v).strip()
                    vals.append(v)
                else:
                    vals.append("")
            if any(vals):
                parsed_rows.append(vals)
        
        if parsed_rows:
            df = pd.DataFrame(parsed_rows)
            sheets[sheet_name] = df
    
    return sheets

def extract_data_rows(df):
    """Extract headers and data rows from LTMC sheet (handles SpreadsheetML metadata rows)"""
    rows = df.values.tolist()
    if len(rows) < 2:
        return [], []
    
    # Find header row: first row with 2+ short ALL-CAPS tokens (SAP field names)
    hdr_idx = None
    for i, row in enumerate(rows[:12]):
        vals = [s(c) for c in row if s(c)]
        caps = sum(1 for v in vals if re.match(r'^[A-Z][A-Z0-9_]{1,25}$', v))
        if caps >= 2:
            hdr_idx = i
            break
    
    if hdr_idx is None:
        return [], []
    
    headers = [s(c) for c in rows[hdr_idx]]
    
    # Skip metadata rows after header (type descriptors, group labels, field descriptions)
    data_start = hdr_idx + 1
    while data_start < len(rows):
        row_str = " ".join(s(c) for c in rows[data_start])
        if re.search(r'E[TDNU][EDA];', row_str):
            data_start += 1; continue
        first = s(rows[data_start][0])
        if '*' in first and len(first) > 30:
            data_start += 1; continue
        break
    
    data_rows = []
    for row in rows[data_start:]:
        cells = [s(c) for c in row]
        if any(cells):
            data_rows.append(cells)
    
    return headers, data_rows

def rows_to_records(headers, data_rows):
    records = []
    for i, row in enumerate(data_rows):
        rec = {headers[j]: (row[j] if j < len(row) else "")
               for j in range(len(headers)) if headers[j]}
        if any(v for v in rec.values()):
            rec["_row"] = i + 1
            records.append(rec)
    return records

# ── Object Detection ─────────────────────────────────────────────────────────

def detect_migration_object(sheets_dict, kb):
    """Auto-detect migration object from file content"""
    # Check title row in any sheet
    for sheet_name, df in sheets_dict.items():
        rows = df.values.tolist()
        for row in rows[:4]:
            for cell in row:
                cell_str = s(cell)
                if "Source Data for Migration Object" in cell_str or "Migration Object:" in cell_str:
                    # Extract object name
                    m = re.search(r'Migration Object[:\s]+(.+)', cell_str)
                    if m:
                        detected = m.group(1).strip().rstrip(".")
                        # Find best match in KB
                        for kb_obj in kb:
                            if detected.lower() in kb_obj.lower() or kb_obj.lower() in detected.lower():
                                return kb_obj
                        return detected
    
    # Try matching by sheet names
    user_sheets = set(sheets_dict.keys())
    best_match = None
    best_score = 0
    
    for kb_obj, kb_data in kb.items():
        kb_sheets = set(kb_data.get("data_sheets", []))
        overlap = len(user_sheets & kb_sheets)
        if overlap > best_score:
            best_score = overlap
            best_match = kb_obj
    
    return best_match if best_score > 0 else None

# ── Universal Validator (Claude AI) ──────────────────────────────────────────

def build_validation_prompt(object_name, kb_data, sheets_records, include_fixes):
    """Build Claude prompt with KB rules + actual data"""
    
    # KB rules summary
    fields_summary = []
    for f in kb_data.get("fields", [])[:80]:  # cap at 80 fields for context
        flag = "MANDATORY" if f.get("mandatory") else "optional"
        sap_f = f.get("sap_field", "")
        ftype = f.get("type", "Text")
        flen = f.get("length", "")
        desc = f.get("field", "")
        sheet = f.get("sheet", "")
        len_str = f"max {flen} chars" if flen and ftype == "Text" else (f"type={ftype}" if ftype else "")
        fields_summary.append(f"  [{sap_f}] {desc} | {flag} | {len_str} | Sheet: {sheet}")
    
    kb_rules = "\n".join(fields_summary)
    
    # Data summary
    data_parts = []
    for sheet_name, records in sheets_records.items():
        if not records: continue
        data_parts.append(f"\n### Sheet: {sheet_name} ({len(records)} records)")
        for i, rec in enumerate(records[:15]):
            clean = {k: v for k, v in rec.items() if not k.startswith("_") and v}
            data_parts.append(f"  Record {i+1}: {json.dumps(clean)}")
        if len(records) > 15:
            data_parts.append(f"  ... ({len(records)-15} more records)")
    
    data_text = "\n".join(data_parts)
    
    fix_instr = "Provide a specific actionable fix for every issue." if include_fixes else "List issues only."
    
    return f"""You are an expert SAP S/4HANA Data Migration Consultant at Syntax.
Validate the following data for migration object: **{object_name}**

## OFFICIAL FIELD RULES FROM LTMC TEMPLATE:
{kb_rules}

## GENERAL SAP LTMC VALIDATION RULES:
- All mandatory fields must be filled — blank mandatory field = CRITICAL (upload fails)
- Text fields exceeding max length cause CNV_DMC_MD_EXTRACTOR032 error
- Date fields must be in YYYYMMDD format — wrong format causes CNV_DMC_MD_EXTRACTOR033
- Indicator fields (single char flags) must be X or blank only — anything else causes CNV_DMC_MD_EXTRACTOR032
- Duplicate key combinations cause DMC_RT_MSG188
- Numeric fields must contain only numbers — text in numeric field causes DMC_RT_MSG222

## DATA TO VALIDATE:
{data_text}

## TASK:
{fix_instr}
Validate all records. Reference SAP technical field names in [BRACKETS].

Return ONLY valid JSON (no markdown):
{{
  "summary": {{
    "object": "{object_name}",
    "total_records": <int>,
    "sheets_checked": [<list>],
    "critical_count": <int>,
    "warning_count": <int>,
    "info_count": <int>,
    "overall_status": "FAIL"|"WARN"|"PASS"
  }},
  "issues": [
    {{
      "record_id": "<record identifier>",
      "sheet": "<sheet name>",
      "sap_structure": "<S_xxx>",
      "field": "<SAP_FIELD_NAME>",
      "field_label": "<Human readable label>",
      "current_value": "<value found or MISSING>",
      "severity": "CRITICAL"|"WARNING"|"INFO",
      "issue": "<[FIELD] description of problem>",
      "fix": "<specific action to fix>",
      "ltmc_error_code": "<error code or blank>"
    }}
  ],
  "recommendations": ["<string>"]
}}"""

def call_claude(prompt, api_key, max_tokens=4000):
    client = anthropic.Anthropic(api_key=api_key)
    response = client.messages.create(
        model="claude-sonnet-4-5",
        max_tokens=max_tokens,
        messages=[{"role": "user", "content": prompt}]
    )
    return response.content[0].text

def parse_claude_json(raw):
    try:
        clean = re.sub(r"```json\s*", "", raw)
        clean = re.sub(r"```\s*", "", clean).strip()
        return json.loads(clean)
    except Exception:
        m = re.search(r"\{.*\}", raw, re.DOTALL)
        if m:
            try: return json.loads(m.group())
            except: pass
    return {"summary": {"overall_status": "ERROR", "critical_count": 0, "warning_count": 0,
                        "info_count": 0, "total_records": 0, "sheets_checked": []},
            "issues": [], "recommendations": ["Could not parse response. Try again."]}

# ── Error Log Analyser ───────────────────────────────────────────────────────

def read_error_log(uploaded_file):
    """Read SAP LTMC error log Excel"""
    try:
        xl = pd.ExcelFile(uploaded_file, engine="openpyxl")
        df = pd.read_excel(xl, sheet_name=xl.sheet_names[0], dtype=str).fillna("")
        return df, None
    except Exception as e:
        return None, str(e)

def group_errors(df):
    """Group errors by unique Message Class + Number combination"""
    col_map = {}
    for col in df.columns:
        cl = col.lower()
        if "type" in cl: col_map["type"] = col
        elif "title" in cl or "message title" in cl: col_map["title"] = col
        elif "class" in cl: col_map["class"] = col
        elif "number" in cl: col_map["number"] = col
        elif "count" in cl: col_map["count"] = col
        elif "date" in cl or "time" in cl: col_map["datetime"] = col
    
    groups = {}
    for _, row in df.iterrows():
        msg_class = s(row.get(col_map.get("class",""), ""))
        msg_num   = s(row.get(col_map.get("number",""), ""))
        msg_type  = s(row.get(col_map.get("type",""), ""))
        msg_title = s(row.get(col_map.get("title",""), ""))
        msg_count = s(row.get(col_map.get("count",""), "1"))
        
        key = f"{msg_class}_{msg_num}"
        if key not in groups:
            groups[key] = {
                "type": msg_type, "class": msg_class, "number": msg_num,
                "title": msg_title, "occurrences": 0, "records": []
            }
        try: groups[key]["occurrences"] += int(msg_count) if msg_count.isdigit() else 1
        except: groups[key]["occurrences"] += 1
        
        # Try to extract record ID from title
        rec_match = re.search(r'Source Record[:\s]+([\w,\s]+)', msg_title)
        if rec_match and len(groups[key]["records"]) < 5:
            groups[key]["records"].append(rec_match.group(1).strip())
    
    return list(groups.values())

def build_error_resolution_prompt(error_groups):
    """Build Claude prompt for error resolution"""
    errors_text = []
    for i, eg in enumerate(error_groups):
        errors_text.append(
            f"{i+1}. Type={eg['type']} | Class={eg['class']} | Number={eg['number']} "
            f"| Occurrences={eg['occurrences']} | Message: {eg['title']}"
        )
    
    return f"""You are a senior SAP S/4HANA Data Migration Consultant at Syntax.
Analyse the following SAP LTMC migration errors and provide resolution guidance.

## ERRORS FROM SAP MIGRATION COCKPIT:
{chr(10).join(errors_text)}

For each error, provide:
1. Root cause explanation
2. Step-by-step resolution (specific SAP config steps, transaction codes, field corrections)
3. SAP community/help URL where this is documented (real SAP URLs only)
4. Preventive measure for future migrations

Return ONLY valid JSON:
{{
  "resolutions": [
    {{
      "error_class": "<class>",
      "error_number": "<number>",
      "error_title": "<title>",
      "error_type": "<type>",
      "occurrences": <int>,
      "root_cause": "<clear explanation>",
      "resolution_steps": ["<step 1>", "<step 2>", ...],
      "sap_reference_url": "<URL to SAP help/community>",
      "sap_t_codes": ["<T-code if applicable>"],
      "preventive_measure": "<how to prevent in future>",
      "severity_assessment": "CRITICAL"|"WARNING"|"INFO"
    }}
  ],
  "overall_summary": "<overall assessment and priority order for resolution>"
}}"""

# ── Export Functions ─────────────────────────────────────────────────────────

def export_validation_excel(result, object_name):
    output = BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        issues = result.get("issues", [])
        summary = result.get("summary", {})
        recs = result.get("recommendations", [])
        
        if issues:
            df_issues = pd.DataFrame([{
                "Record ID": i.get("record_id",""),
                "Sheet": i.get("sheet",""),
                "SAP Structure": i.get("sap_structure",""),
                "SAP Field": i.get("field",""),
                "Field Label": i.get("field_label",""),
                "Current Value": i.get("current_value",""),
                "Severity": i.get("severity",""),
                "Issue Description": i.get("issue",""),
                "Fix / Solution": i.get("fix",""),
                "LTMC Error Code": i.get("ltmc_error_code",""),
            } for i in issues])
            df_issues.to_excel(writer, index=False, sheet_name="Validation Issues")
            ws = writer.sheets["Validation Issues"]
            for col in ws.columns:
                ws.column_dimensions[col[0].column_letter].width = min(
                    max(len(str(c.value or "")) for c in col)+4, 55)
        
        df_sum = pd.DataFrame([{"Metric": k, "Value": str(v)} for k,v in summary.items()])
        df_sum.to_excel(writer, index=False, sheet_name="Summary")
        
        if recs:
            pd.DataFrame({"Recommendations": recs}).to_excel(
                writer, index=False, sheet_name="Recommendations")
    
    output.seek(0)
    return output

def export_error_resolution_excel(resolutions_data, error_groups):
    output = BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        resolutions = resolutions_data.get("resolutions", [])
        
        if resolutions:
            rows = []
            for r in resolutions:
                rows.append({
                    "Error Class": r.get("error_class",""),
                    "Error Number": r.get("error_number",""),
                    "Error Type": r.get("error_type",""),
                    "Message Title": r.get("error_title",""),
                    "Occurrences": r.get("occurrences",0),
                    "Severity": r.get("severity_assessment",""),
                    "Root Cause": r.get("root_cause",""),
                    "Resolution Steps": " | ".join(r.get("resolution_steps",[])),
                    "SAP T-Codes": ", ".join(r.get("sap_t_codes",[])),
                    "SAP Reference URL": r.get("sap_reference_url",""),
                    "Preventive Measure": r.get("preventive_measure",""),
                })
            df = pd.DataFrame(rows)
            df.to_excel(writer, index=False, sheet_name="Error Resolutions")
            ws = writer.sheets["Error Resolutions"]
            for col in ws.columns:
                ws.column_dimensions[col[0].column_letter].width = min(
                    max(len(str(c.value or "")) for c in col)+4, 60)
        
        summary_text = resolutions_data.get("overall_summary","")
        if summary_text:
            pd.DataFrame({"Overall Summary": [summary_text]}).to_excel(
                writer, index=False, sheet_name="Summary")
    
    output.seek(0)
    return output

