        with k2: st.markdown(kpi_html(summary.get("total_records",0), "Records"), unsafe_allow_html=True)
        with k3: st.markdown(kpi_html(summary.get("critical_count",0), "Critical", "err"), unsafe_allow_html=True)
        with k4: st.markdown(kpi_html(summary.get("warning_count",0), "Warnings", "wrn"), unsafe_allow_html=True)
        with k5: st.markdown(kpi_html(summary.get("info_count",0), "Info", "inf"), unsafe_allow_html=True)
        
        st.markdown("<br>", unsafe_allow_html=True)
        
        if overall == "PASS" and not issues:
            st.markdown('<div class="ok-banner">✅ All checks passed — data looks ready for LTMC upload!</div>', unsafe_allow_html=True)
        else:
            crits = [i for i in issues if i.get("severity")=="CRITICAL"]
            warns = [i for i in issues if i.get("severity")=="WARNING"]
            infos = [i for i in issues if i.get("severity")=="INFO"]
            
            t1,t2,t3,t4 = st.tabs([
                f"🔴 Critical ({len(crits)})",
                f"🟡 Warnings ({len(warns)})",
                f"🔵 Info ({len(infos)})",
                "📋 All Issues"
            ])
            with t1:
                [render_issue(i, include_fixes) for i in crits] if crits else st.success("No critical issues.")
            with t2:
                [render_issue(i, include_fixes) for i in warns] if warns else st.success("No warnings.")
            with t3:
                [render_issue(i, include_fixes) for i in infos] if infos else st.info("No informational notes.")
            with t4:
                if issues: [render_issue(i, include_fixes) for i in issues]
                else: st.success("No issues found.")
        
        if recs:
            st.markdown("### 💬 Recommendations")
